const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const { ChatRouter } = require('../chat/router');
const { verifySessionToken } = require('../auth/session');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', async (req, socket, head) => {
  const user = await verifySessionToken(req);
  if (!user) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  const protocolHeader = req.headers['sec-websocket-protocol'] || '';
  const parts = protocolHeader.split(',').map(s => s.trim());
  const channelTag = parts.find(p => p.startsWith('customer-chat-'));
  const customerId = channelTag ? channelTag.replace('customer-chat-', '') : null;

  // Ensure caller is the authenticated customer or an authorized support agent
  if (!customerId || (user.id !== customerId && user.role !== 'SUPPORT_AGENT')) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(req, socket, head, (ws) => {
    ws.customerId = customerId;
    ChatRouter.routeToCustomerLiveStream(customerId, ws);
  });
});

server.listen(8081);
